  var CHAR_GUARD_KEY = 'kdn_char_prompt_guard_v1';
  var CHAR_GUARD_GLOBAL_KEY = 'kdn_char_prompt_guard_global_v1';
  function isGuardGlobalEnabled() {
    try { return hostWindow.localStorage.getItem(CHAR_GUARD_GLOBAL_KEY) !== '0'; } catch (e) { return true; }
  }
  function setGuardGlobalEnabled(on) {
    try {
      hostWindow.localStorage.setItem(CHAR_GUARD_GLOBAL_KEY, on ? '1' : '0');
      return true;
    } catch (e) { return false; }
  }
  var COMPILE_V1_KEY = 'kdn_char_prompt_compile_v1';
  var COMPILE_V2_KEY = 'kdn_char_prompt_compile_v2';
  var COMPILE_VARIANT_KEY = 'kdn_char_compile_variant';
  var COMPILE_GENDER_KEY = 'kdn_char_compile_gender';
  function getGuardDefault() { return DEFAULT_CHAR_GUARD_PROMPT; }
  function getGuardPreset(key) {
    if (key === 'atriA') return GUARD_PRESET_ATRI_A;
    if (key === 'atriB') return GUARD_PRESET_ATRI_B;
    return DEFAULT_CHAR_GUARD_PROMPT;
  }
  function getEffectiveGuardPrompt() {
    try {
      var custom = hostWindow.localStorage.getItem(CHAR_GUARD_KEY);
      if (custom && custom.trim().length > 20) return custom.trim();
    } catch (e) {}
    return DEFAULT_CHAR_GUARD_PROMPT;
  }
  function withGuard(prompt) {
    var g = getEffectiveGuardPrompt();
    var p = String(prompt || '').trim();
    if (!g) return p ? (p + '\n\n' + AI_ANTI_HIJACK) : AI_ANTI_HIJACK;
    return p ? (g + '\n\n' + p + '\n\n' + AI_ANTI_HIJACK) : (g + '\n\n' + AI_ANTI_HIJACK);
  }
  function getCompileVariant() {
    try { return hostWindow.localStorage.getItem(COMPILE_VARIANT_KEY) === '2' ? 2 : 1; } catch (e) { return 1; }
  }
  function setCompileVariant(v) {
    try {
      if (Number(v) === 2) hostWindow.localStorage.setItem(COMPILE_VARIANT_KEY, '2');
      else hostWindow.localStorage.removeItem(COMPILE_VARIANT_KEY);
      return true;
    } catch (e) { return false; }
  }
  function getCompileGenderSetting() {
    try {
      var v = hostWindow.localStorage.getItem(COMPILE_GENDER_KEY);
      return (v === '男' || v === '女') ? v : 'auto';
    } catch (e) { return 'auto'; }
  }
  function setCompileGenderSetting(v) {
    try {
      if (v === '男' || v === '女') hostWindow.localStorage.setItem(COMPILE_GENDER_KEY, v);
      else hostWindow.localStorage.removeItem(COMPILE_GENDER_KEY);
      return true;
    } catch (e) { return false; }
  }
  function applyCompileBody(text, gender) {
    var t = String(text || '');
    var ph = '__KDN_PRIV_BODY__';
    if (t.indexOf(ph) < 0) return t;
    var isMale = String(gender || '').indexOf('男') >= 0;
    var body = isMale ? String(COMPILE_BODY_MALE) : String(COMPILE_BODY_FEMALE);
    if (!body) return t.split(ph).join('');
    return t.split(ph).join(body);
  }
  function resolveCompileGenderOuter() {
    var s = getCompileGenderSetting();
    if (s === '男' || s === '女') return s;
    try {
      var st = hostWindow.SillyTavern && hostWindow.SillyTavern.getContext ? hostWindow.SillyTavern.getContext() : null;
      var me = st && st.characters && st.characterId >= 0 ? st.characters[st.characterId] : null;
      if (me && me.tags && me.tags.indexOf('男') >= 0) return '男';
    } catch (e) {}
    return '女';
  }

