  function mediaHostDb(){return new Promise(function(resolve,reject){var request=hostWindow.indexedDB.open('shn_phone_images',1);request.onupgradeneeded=function(){if(!request.result.objectStoreNames.contains('images'))request.result.createObjectStore('images');};request.onsuccess=function(){resolve(request.result);};request.onerror=function(){reject(new Error('本机图片数据库不可用'));};});}
