  function sanitizeFailedCharacters(agentData) {
    if (!agentData || typeof agentData !== 'object') return false;
    var changed = false;
    if (agentData.characters && typeof agentData.characters === 'object') {
      Object.keys(agentData.characters).forEach(function (k) {
        var it = agentData.characters[k];
        var nm = (it && (it.name || it.originalName)) || k;
        // 清理旧档被楼层自动生成或登记骨架的内置同人角色（保留用户手动 custom 创建项与徐朵朵）
        if ((isTongrenBuiltInCharacter(k) || isTongrenBuiltInCharacter(nm)) && (!it || it.source !== 'custom')) {
          delete agentData.characters[k];
          changed = true;
        }
      });
    }
    if (agentData.failures && typeof agentData.failures === 'object') {
      Object.keys(agentData.failures).forEach(function (k) {
        var f = agentData.failures[k];
        var errMsg = String((f && f.lastError) || '');
        if (isTongrenBuiltInCharacter(k) || errMsg.indexOf('getEffectiveCompilePrompt') >= 0 || errMsg.indexOf('ReferenceError') >= 0 || errMsg.indexOf('not defined') >= 0) {
          delete agentData.failures[k];
          changed = true;
        }
      });
    }
    return changed;
  }

  function readChatAgentVariables() {
    var reader = getVariablesReader();
    if (!reader) return { version: 1, characters: {}, failures: {}, ignored: {} };
    try {
      var cv = reader({ type: 'chat' });
      if (cv && typeof cv === 'object' && cv.kdn_char_agent && typeof cv.kdn_char_agent === 'object') {
        var agent = cv.kdn_char_agent;
        if (!agent.characters || typeof agent.characters !== 'object') agent.characters = {};
        if (!agent.failures || typeof agent.failures !== 'object') agent.failures = {};
        if (!agent.ignored || typeof agent.ignored !== 'object' || Array.isArray(agent.ignored)) agent.ignored = {};
        if (sanitizeFailedCharacters(agent)) {
          writeChatAgentVariables(agent);
        }
        return agent;
      }
    } catch (e) {}
    return { version: 1, characters: {}, failures: {}, ignored: {} };
  }

  function writeChatAgentVariables(agentData) {
    var replace = getVariablesReplacer(), reader = getVariablesReader();
    if (!replace || !reader) return false;
    try {
      var cv = reader({ type: 'chat' }) || {};
      if (typeof cv !== 'object' || Array.isArray(cv)) cv = {};
      cv.kdn_char_agent = agentData;
      replace(cv, { type: 'chat' });
      return true;
    } catch (e) {
      console.warn('[都市神豪] 写入聊天角色变量失败:', e);
      return false;
    }
  }

