  function normalizeTextNewlines(str) {
    if (!str) return '';
    var s = String(str).replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n').replace(/\r\n/g, '\n');
    return s.replace(/\n{3,}/g, '\n\n').trim();
  }

