  function hudHtml() {
    if (HUD_SOURCE && HUD_SOURCE.charAt(0) === '<') return HUD_SOURCE;
    var card = currentCard();
    var ext = card && card.data && card.data.extensions;
    var value = ext && ext.kaidan_note && ext.kaidan_note.hud_html;
    return typeof value === 'string' ? value : '';
  }

  function hudSourceKey(source) {
    source = String(source || '');
    var hash = 5381;
    for (var i = 0; i < source.length; i++) hash = ((hash << 5) + hash) ^ source.charCodeAt(i);
    return source.length + ':' + (hash >>> 0).toString(36);
  }

  function pickStatContainer(source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return null;
    for (var holder of [source, source.variables, source.data]) {
      if (holder && typeof holder.stat_data === 'object' && holder.stat_data !== null && !Array.isArray(holder.stat_data)) return { holder: holder, key: 'stat_data' };
    }
    return null;
  }

  function pickStatFromSource(source) {
    if (!source || typeof source !== 'object') return null;
    var direct = source.stat_data;
    if (direct && typeof direct === 'object' && !Array.isArray(direct)) return direct;
    var variableStat = source.variables && source.variables.stat_data;
    if (variableStat && typeof variableStat === 'object' && !Array.isArray(variableStat)) return variableStat;
    var dataStat = source.data && source.data.stat_data;
    if (dataStat && typeof dataStat === 'object' && !Array.isArray(dataStat)) return dataStat;
    if (source.user && typeof source.user === 'object') return source;
    return null;
  }

  function readLatestStat() {
    try {
      if (typeof getVariables === 'function') {
        var latestVariables = getVariables({ type: 'message', message_id: 'latest' });
        var stat1 = pickStatFromSource(latestVariables);
        if (stat1) return stat1;
      }
    } catch (e) {}
    try {
      var mvu = getMvu();
      if (mvu && typeof mvu.getMvuData === 'function') {
        var latestMvu = mvu.getMvuData({ type: 'message', message_id: 'latest' });
        var stat2 = pickStatFromSource(latestMvu);
        if (stat2) return stat2;
      }
    } catch (e) {}
    try {
      if (typeof getAllVariables === 'function') {
        var allVars = getAllVariables();
        var stat3 = pickStatFromSource(allVars);
        if (stat3) return stat3;
      }
    } catch (e) {}
    try {
      var readVariables = getVariablesReader();
      if (readVariables) {
        var persisted = readVariables({ type: 'message', message_id: 'latest' });
        var stat4 = pickStatFromSource(persisted);
        if (stat4) return stat4;
      }
    } catch (e) {}
    return null;
  }

  function commitStat(stat) {
    if (!stat || typeof stat !== 'object') return false;
    var encoded = '';
    try { encoded = JSON.stringify(stat); } catch (e) { return false; }
    if (!encoded) return false;
    if (runtime.committedStat && encoded === runtime.committedStatJson) return true;
    var snapshot = null;
    try { snapshot = JSON.parse(encoded); } catch (e) { return false; }
    if (!snapshot || typeof snapshot !== 'object') return false;
    runtime.committedStat = snapshot;
    runtime.committedStatJson = encoded;
    runtime.statRevision += 1;
    return true;
  }

  function commitMvuData(data) {
    var stat = pickStatFromSource(data);
    return !!(stat && commitStat(stat));
  }

  function sameStatValue(a, b) {
    if (a === b) return true;
    if (!a || !b || typeof a !== 'object' || typeof b !== 'object' || Array.isArray(a) !== Array.isArray(b)) return false;
    var keys = Object.keys(a);
    if (keys.length !== Object.keys(b).length) return false;
    return keys.every(function (key) { return Object.prototype.hasOwnProperty.call(b, key) && sameStatValue(a[key], b[key]); });
  }

  function awaitMvuPersistence(variables, context) {
    var stat = pickStatFromSource(variables), messageId = bridgeMessageId(), chatEpoch = runtime.chatEpoch;
    if (!stat || messageId === null) return;
    // The MVU transaction is still mutable here: later listeners, schema
    // reconciliation and BEFORE_MESSAGE_UPDATE can replace stat_data. Keep
    // this transaction reference; never use an unrelated stored floor as target.
    var target = { messageId: messageId, stat: JSON.parse(JSON.stringify(stat)), source: context || variables };
    runtime.persistTarget = target;
    function check(attempt) {
      schedule('stat-finalize', function () {
        if (runtime.destroyed || runtime.chatEpoch !== chatEpoch || runtime.persistTarget !== target
          || runtime.phase !== 'awaiting-persist' || !bridgeMessageMatches(messageId)) return;
        if (syncLatestStat(chatEpoch, true)) return;
        if (attempt < 119) check(attempt + 1);
      }, attempt === 0 ? 300 : 250);
    }
    check(0);
  }

