  function escPipe(text) {
    return String(text).replace(/\|/g, '\\|');
  }

  function getSlashRunner() {
    var helper = getTavernHelper();
    if (helper && typeof helper.triggerSlash === 'function') {
      return function (command) { return helper.triggerSlash(command); };
    }
    try {
      if (typeof triggerSlash === 'function') return function (command) { return triggerSlash(command); };
    } catch (e) {}
    return null;
  }

  function runSlash(command) {
    var runner = getSlashRunner();
    if (!runner) return Promise.reject(new Error('酒馆助手命令接口尚未就绪'));
    try { return Promise.resolve(runner(command)); }
    catch (error) { return Promise.reject(error); }
  }

  function hostInputValue() {
    try {
      var input = hostDocument.querySelector('#send_textarea');
      if (!input) return '';
      return String(input.value != null ? input.value : input.textContent || '');
    } catch (e) { return ''; }
  }

  function hostInputText() {
    return hostInputValue().trim();
  }

  function doSend(text) {
    return runSlash('/send ' + escPipe(text) + ' | /trigger').then(function () { return true; });
  }

  function doInput(text) {
    if (hostInputText()) return Promise.reject(new Error('输入框已有内容，请先清空或自行合并'));
    return runSlash('/setinput ' + escPipe(text)).then(function () { return true; });
  }

  function doAppendInput(text) {
    var current = hostInputValue().replace(/[\t ]+$/gm, '').replace(/\s+$/, '');
    var combined = current ? current + '\n' + text : text;
    var commandText = escPipe(combined).replace(/\r?\n/g, '{{newline}}');
    return runSlash('/setinput ' + commandText).then(function () { return true; });
  }

  function socialChatKind(){
    try{var ctx=hostWindow.SillyTavern.getContext();if(!ctx||!Array.isArray(ctx.chat)||!ctx.chat.length)return null;return String(ctx.chat[0].mes||'').includes('thomas-social-v1:new-chat')?'new':'legacy';}catch(e){return null;}
  }
  function chatHostStateSnapshot(){
    var hostGenerating = null;
    try { if (typeof runtime.hostIsGenerating === 'function') hostGenerating = runtime.hostIsGenerating(); } catch (e) {}
    // Recover a missed ending event only after MVU completion and an exact saved-data reread.
    if (hostGenerating === false && !runtime.destroyed && !runtime.isGenerating && !runtime.storyPreparing
      && runtime.storyGenerating && ['stable','awaiting-persist','aborted'].indexOf(runtime.phase) >= 0
      && syncLatestStat(runtime.chatEpoch, true)) {
      runtime.storyGenerating = false;
      runtime.storyGateToken = null;
    }
    // A stopped generation or a late load may outlive the bounded polling window.
    // Only reread saved data while no story/MVU work is active. A pending target
    // still has to match its floor and final transaction values.
    if (!runtime.destroyed && !runtime.isGenerating && !runtime.storyPreparing && !runtime.storyGenerating
      && ['cold','switching','aborted','awaiting-persist'].indexOf(runtime.phase) >= 0) syncLatestStat(runtime.chatEpoch, true);
    return {epoch:runtime.chatEpoch,busy:hostGenerating===true||runtime.destroyed||runtime.isGenerating||runtime.awaitingPersist||runtime.phase==='switching'||runtime.phase==='updating',preparing:!!runtime.storyPreparing,storyGenerating:!!runtime.storyGenerating,gateReady:!!runtime.storyGateReady,phase:runtime.phase,persistencePending:!!runtime.persistTarget};
  }

  // V1.7.0：把「忙」的原因说清楚，而不是一律「请稍后再试」
  function hostBusyReason(host){
    host=host||{};
    if(host.storyGenerating) return '上次剧情生成未正常结束';
    if(host.preparing) return '正文正在准备';
    if(host.phase==='switching') return '正在切换聊天';
    if(host.phase==='updating') return '变量更新尚未完成';
    if(host.persistencePending) return '变量尚未保存完成';
    if(host.busy) return '酒馆仍在生成中';
    return '';
  }
  // V1.7.0：卡死状态复位。只在酒馆明确空闲时执行，绝不打断真实生成。
  function recoverHostState(){
    var before=chatHostStateSnapshot(),cleared=[];
    var nativeBusy=null;
    try { if (typeof runtime.hostIsGenerating==='function') nativeBusy=runtime.hostIsGenerating(); } catch(e) {}
    if (nativeBusy===true) throw Error('酒馆正在生成中，不能强制复位；请等生成结束或先停止生成');
    if (runtime.destroyed) throw Error('本页已失效，请刷新酒馆页面后重试');
    if (runtime.storyPreparing) { runtime.storyPreparing=false; cleared.push('剧情准备标志'); }
    if (runtime.storyGenerating) { runtime.storyGenerating=false; cleared.push('剧情生成标志'); }
    if (runtime.storyGateToken!==null&&runtime.storyGateToken!==undefined) { runtime.storyGateToken=null; cleared.push('剧情门令牌'); }
    if (runtime.storyGateReady) { runtime.storyGateReady=false; cleared.push('门就绪标志'); }
    if (runtime.isGenerating) { runtime.isGenerating=false; cleared.push('生成标志'); }
    if (runtime.awaitingPersist) { runtime.awaitingPersist=false; cleared.push('待保存标志'); }
    if (runtime.persistTarget) { runtime.persistTarget=null; cleared.push('保存目标'); }
    if (runtime.phase==='switching'||runtime.phase==='updating'||runtime.phase==='awaiting-persist') {
      cleared.push('阶段 '+runtime.phase+' → stable');
      runtime.phase='stable';
    }
    var after=chatHostStateSnapshot();
    if (after.busy||after.preparing||after.storyGenerating) {
      throw Error('复位后仍被判定为忙碌（'+((typeof hostBusyReason==='function'?hostBusyReason(after):''))+'），请刷新酒馆页面');
    }
    return {cleared:cleared,before:before,after:after};
  }
