  var id=bridgeMessageId(),helper=getTavernHelper(),swipe=0;
  if(!shopScope()||id===null||!helper||typeof helper.getChatMessages!=='function'){var error=Error('当前聊天与楼层接口尚未就绪，请稍后重试');error.code='SHOP_CONTEXT_NOT_READY';throw error;}
