  var io,rec,helper=getTavernHelper();try{io=shopRead(ctx);rec=ThomasShop.state(io.stat).购买回执[id];if(!rec)throw Error('购买回执不存在');if(rec.收据已写)return Promise.resolve(true);if(!helper||typeof helper.setChatMessages!=='function')throw Error('购买已保存，剧情收据写入接口未就绪');}catch(e){return Promise.reject(e)}
