  var task=Promise.resolve();
  if(!row.message.includes(marker)){try{shopGuard(ctx);task=Promise.resolve(helper.setChatMessages([Object.assign({},row,{message:row.message.trimEnd()+ThomasShop.receipt(rec)})],{refresh:'affected'}))}catch(e){task=Promise.reject(e)}}
