  version:'1.5.10',prepareFinance:function(peer){if(typeof prepareCharacterFinance!=='function')return Promise.reject(Error('人物财务接口尚未就绪，请重载脚本'));return prepareCharacterFinance(peer)},financeStatus:function(peer){return typeof characterFinanceStatus==='function'?characterFinanceStatus(peer):{busy:false,error:''}},context:shopContext,status:function(){return SHOP_BRIDGE.status()},
