  function exposeBridge(target) {
    if (!target) return;
    try {
      target.__kdnStatBridge = getStat;
      target.__kdnSocialChatKind = socialChatKind;
      target.__kdnChatHostState = chatHostStateSnapshot;
      target.__kdnSend = doSend;
      target.__kdnInput = doInput;
      target.__kdnAi = AI_BRIDGE;
      target.__kdnShop = SHOP_BRIDGE;
      target.__kdnEconomy = ECONOMY_BRIDGE;
      target.__kdnDelegation = DELEGATION_BRIDGE;
      target.__kdnReputation = REPUTATION_BRIDGE;
      target.__kdnMedia = MEDIA_BRIDGE;
      target.__kdnCharAgent = CHAR_AGENT_BRIDGE;
      target.__kdnBond = writeCharacterBond;
      target.__kdnRemove = removeMvuRecord;
      target.__kdnMutateStat = mutateMvuStat;
    } catch (e) {}
  }

  function clearBridge(target) {
    if (!target) return;
    try { if (target.__kdnSocialChatKind === socialChatKind) delete target.__kdnSocialChatKind; } catch(e) {}
    try { if (target.__kdnChatHostState === chatHostStateSnapshot) delete target.__kdnChatHostState; } catch(e) {}
    try { if (target.__kdnStatBridge === getStat) delete target.__kdnStatBridge; } catch (e) {}
    try { if (target.__kdnSend === doSend) delete target.__kdnSend; } catch (e) {}
    try { if (target.__kdnInput === doInput) delete target.__kdnInput; } catch (e) {}
    try { if (target.__kdnAi === AI_BRIDGE) delete target.__kdnAi; } catch (e) {}
    try { if (target.__kdnDelegation === DELEGATION_BRIDGE) delete target.__kdnDelegation; } catch (e) {}
    try { if (target.__kdnEconomy === ECONOMY_BRIDGE) delete target.__kdnEconomy; } catch (e) {}
    try { if (target.__kdnShop === SHOP_BRIDGE) delete target.__kdnShop; } catch (e) {}
    try { if (target.__kdnReputation === REPUTATION_BRIDGE) delete target.__kdnReputation; } catch (e) {}
    try { if (target.__kdnMedia === MEDIA_BRIDGE) delete target.__kdnMedia; } catch (e) {}
    try { if (target.__kdnCharAgent === CHAR_AGENT_BRIDGE) delete target.__kdnCharAgent; } catch (e) {}
    try { if (target.__kdnBond === writeCharacterBond) delete target.__kdnBond; } catch (e) {}
    try { if (target.__kdnRemove === removeMvuRecord) delete target.__kdnRemove; } catch (e) {}
    try { if (target.__kdnMutateStat === mutateMvuStat) delete target.__kdnMutateStat; } catch (e) {}
  }

  function clearTimer(name) {
    var id = runtime.timers[name];
    if (id === undefined) return;
    try { hostWindow.clearTimeout(id); } catch (e) {}
    delete runtime.timers[name];
  }

  function schedule(name, fn, delay) {
    clearTimer(name);
    runtime.timers[name] = hostWindow.setTimeout(function () {
      delete runtime.timers[name];
      if (!runtime.destroyed) fn();
    }, delay);
  }

  function bindEvent(type, handler) {
    var on = getEventOn();
    if (!type || !on) return false;
    try {
      var listener = on(type, handler);
      if (listener && typeof listener.stop === 'function') {
        runtime.stops.push(function () { listener.stop(); });
      }
      return true;
    } catch (e) {
      return false;
    }
  }

